for cid, probes in PROBES.items():
    p = CASES / f"{cid}.json"
    raw = json.loads(p.read_text(encoding="utf-8"))
    ids = {f["id"] for f in raw["facts"]}
    assert set(probes) <= ids, set(probes) - ids
    for f in raw["facts"]:
        if f["id"] in probes:
            f["recall_probes"] = probes[f["id"]]
    p.write_text(json.dumps(raw, indent=1, ensure_ascii=False), encoding="utf-8")
    print(cid, sum(len(v) for v in probes.values()), "probes;", "missing:", sorted(ids - set(probes)))
